-- ============================================================
-- SalesPlace — مستهدفات المبيعات الشهرية لكل مشروع (sales_targets)
-- جدول جديد بالكامل — لا يمسّ أي دالة أو جدول موجود حالياً
-- شغّل هذا الملف كاملاً مرة واحدة في Supabase SQL editor
-- ============================================================

create table if not exists sales_targets (
  id bigint generated always as identity primary key,
  year integer not null default 2026,
  sector text,                 -- الأوسط / الغربي / الشرقي
  destination text,
  project_code text,
  project_name text not null,
  developer_kind text,         -- NHC / مطورين / لم يحدد
  month_num integer not null check (month_num between 1 and 12),
  target numeric not null default 0
);
create unique index if not exists sales_targets_uk on sales_targets (year, project_code, month_num);
create index if not exists sales_targets_lookup_idx on sales_targets (year, sector, developer_kind, month_num);

alter table sales_targets enable row level security;

drop policy if exists sales_targets_read on sales_targets;
create policy sales_targets_read on sales_targets
  for select using (true);

-- إجمالي المستهدف + تفصيل حسب المشروع لنفس فلاتر شاشة مبيعاتنا (لا يتطلب صلاحية إدارية،
-- بنفس نمط get_sales_report/get_project_totals الموجودتين أصلاً واللتين تُستدعيان بلا مصادقة إدارية)
create or replace function get_target_summary(p_year int, p_from_month int, p_to_month int, p_sector text default null, p_dev_kind text default null)
returns jsonb
language plpgsql
security definer
as $$
declare
  v_total numeric;
  v_by_project jsonb;
begin
  select coalesce(sum(target),0) into v_total
  from sales_targets
  where year = p_year and month_num between p_from_month and p_to_month
    and (p_sector is null or sector = p_sector)
    and (p_dev_kind is null or
         (p_dev_kind = 'nhc' and developer_kind = 'NHC') or
         (p_dev_kind = 'other' and developer_kind <> 'NHC'));

  select coalesce(jsonb_agg(jsonb_build_object('project_name', project_name, 'target', target_sum)), '[]'::jsonb)
  into v_by_project
  from (
    select project_name, sum(target) as target_sum
    from sales_targets
    where year = p_year and month_num between p_from_month and p_to_month
      and (p_sector is null or sector = p_sector)
      and (p_dev_kind is null or
           (p_dev_kind = 'nhc' and developer_kind = 'NHC') or
           (p_dev_kind = 'other' and developer_kind <> 'NHC'))
    group by project_name
  ) t;

  return jsonb_build_object('total', v_total, 'by_project', v_by_project);
end;
$$;

-- ============================================================
-- تحميل أولي: ٢٣٧ مشروعاً × ١٢ شهراً = ٢٨٤٤ صفاً من ملف المستهدفات المرفق (سنة ٢٠٢٦)
-- on conflict يجعل إعادة تشغيل هذا الجزء آمنة (يحدّث الأرقام بدل التكرار)
-- ============================================================
on conflict (year, project_code, month_num) do update set target = excluded.target;
